<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Config;use StudPulse\Http\ApiError;final class MpeiMailbox{private const SMTP='smtp://mail.mpei.ru:25';public static function available():bool{return Config::bool('MPEI_MAIL_ENABLED')&&function_exists('proc_open')&&extension_loaded('sodium');}public static function python():string{$configured=Config::get('MPEI_MAIL_PYTHON');if($configured!=='')return$configured;$path=Config::storage().'/mail/python-path';$installed=is_readable($path)?trim((string)file_get_contents($path)):'';return str_starts_with($installed,'/')?$installed:'python3';}public static function caFile():string{return self::installedCaFile();}public static function installedCaFile():string{return Config::storage().'/mail/mpei-ca-chain.pem';}public static function caSource():string{return Config::get('MPEI_MAIL_CA_FILE','~/mpei-ca-chain.pem');}public static function shortLogin(string$login):?string{$login=preg_replace('/@mpei\.ru$/iD','',trim($login));return preg_match('/^[A-Za-z0-9._-]{1,64}$/D',$login)&&filter_var($login.'@mpei.ru',FILTER_VALIDATE_EMAIL)?$login:null;}public static function read(string$action,string$login,#[\SensitiveParameter]string$password,array$params=[]):array{if(!self::available())throw new ApiError(503,'MPEI_MAIL_DISABLED','Почта МЭИ недоступна в конфигурации сервера.');$output=self::temporaryFile();$keep=false;try{$process=@proc_open([self::python(),ROOT.'/scripts/mpei-mail.py'],[0=>['pipe','r'],1=>$output,2=>['file',PHP_OS_FAMILY==='Windows'?'NUL':'/dev/null','a']],$pipes);if(!is_resource($process))throw new ApiError(503,'MPEI_MAIL_PYTHON','Не удалось запустить серверный Python для почты.');try{self::write($pipes[0],json_encode(['action'=>$action,'login'=>self::shortLogin($login),'password'=>$password,'caFile'=>self::caFile(),'folderNames'=>['sent'=>Config::get('MPEI_MAIL_SENT_FOLDER'),'trash'=>Config::get('MPEI_MAIL_TRASH_FOLDER')],]+$params,JSON_THROW_ON_ERROR));}finally{fclose($pipes[0]);$status=proc_close($process);}rewind($output);$line=fgets($output,16*1024*1024);$result=$line===false?null:json_decode($line,true);if($status!==0||!is_array($result))throw new ApiError(503,'MPEI_MAIL_PYTHON','Python для почты не ответил. Проверьте MPEI_MAIL_PYTHON и настройку запуска.');if(!isset($result['data']))throw match($result['error']??''){'auth'=>new ApiError(403,'MPEI_MAIL_AUTH','Exchange отклонил вход. При смене пароля войдите в БАРС заново.'),'ca'=>new ApiError(503,'MPEI_MAIL_CA','Python не смог загрузить цепочку сертификатов МЭИ. Проверьте MPEI_MAIL_CA_FILE и права чтения.'),'tls'=>new ApiError(502,'MPEI_MAIL_TLS','Не удалось проверить сертификат mail.mpei.ru. Проверьте цепочку сертификатов МЭИ.'),'network'=>new ApiError(502,'MPEI_MAIL_NETWORK','Exchange недоступен с хостинга. Повторите позже.'),'missing'=>new ApiError(404,'MPEI_MAIL_MESSAGE','Письмо больше недоступно.'),'attachment'=>new ApiError(404,'MPEI_MAIL_ATTACHMENT','Вложение не найдено.'),'changed'=>new ApiError(409,'MPEI_MAIL_INBOX_CHANGED','Почтовая папка изменилась. Обновите список писем.'),'folder'=>new ApiError(404,'MPEI_MAIL_FOLDER','Exchange не показал эту почтовую папку.'),'delete_unsupported'=>new ApiError(409,'MPEI_MAIL_DELETE_UNSUPPORTED','Exchange не поддерживает удаление отдельного письма из корзины. Удалите его через Outlook.'),'delete_incomplete'=>new ApiError(502,'MPEI_MAIL_DELETE_INCOMPLETE','Exchange не подтвердил удаление письма. Повторите попытку.'),'size'=>new ApiError(413,'MPEI_MAIL_FILE_SIZE','Сервер отклонил обработку письма объёмом больше 128 МиБ.'),default=>self::upstream(),};if($action!=='attachment')return$result['data'];$file=self::temporaryFile();try{if(stream_copy_to_stream($output,$file)===false||!rewind($file))throw self::temporaryFailure();$keep=true;return[self::safeName($result['data']['name']),$file];}finally{if(!$keep)fclose($file);}}finally{fclose($output);}}public static function send(string$login,#[\SensitiveParameter]string$password,string$from,string$to,$message):void{[$sent,$code,$error]=self::upload(self::SMTP,$login,$password,$message,[CURLOPT_PROTOCOLS=>CURLPROTO_SMTP,CURLOPT_USE_SSL=>CURLUSESSL_ALL,CURLOPT_MAIL_FROM=>"<$from>",CURLOPT_MAIL_RCPT=>["<$to>"],]);if($code===535||$error===67)throw new ApiError(403,'MPEI_MAIL_SMTP_AUTH','SMTP МЭИ отклонил вход с университетской учётной записью.');if($code>=400)throw new ApiError(502,'MPEI_MAIL_REJECTED','SMTP МЭИ отклонил письмо (код '.$code.').');if(!$sent||$code!==250){if(ftell($message)>0)throw new ApiError(502,'MPEI_MAIL_DELIVERY_UNKNOWN','Подтверждение отправки не получено. Проверьте доставку перед повторной отправкой.');throw match($error){77=>new ApiError(503,'MPEI_MAIL_CA','SMTP не смог прочитать цепочку сертификатов. Запустите setup-worker.sh.'),35,60=>new ApiError(502,'MPEI_MAIL_SMTP_TLS','Не удалось проверить TLS при подключении к SMTP МЭИ.'),6,7,28=>new ApiError(502,'MPEI_MAIL_SMTP_NETWORK','Хостинг не смог подключиться к SMTP МЭИ на порту 25.'),default=>new ApiError(502,'MPEI_MAIL_SMTP',"Отправка через SMTP не подтверждена (cURL $error, SMTP $code)."),};}}public static function saveSent(string$login,#[\SensitiveParameter]string$password,$message):?bool{if(Config::get('MPEI_MAIL_SAVE_SENT','true')==='false')return null;$folder=self::read('sent-folder',$login,$password)['folder']??'';if(!preg_match('/^[^{}\x00-\x1f\x7f]{1,120}$/uD',$folder))return false;$path=rawurlencode(mb_convert_encoding($folder,'UTF7-IMAP','UTF-8'));[$saved]=self::upload("imaps://mail.mpei.ru:993/$path",$login,$password,$message,[CURLOPT_PROTOCOLS=>CURLPROTO_IMAPS,CURLOPT_LOGIN_OPTIONS=>'AUTH=PLAIN',]);return$saved;}private static function upload(string$url,string$login,#[\SensitiveParameter]string$password,$message,array$options):array{if(!rewind($message)||!($ch=curl_init($url)))throw self::upstream();curl_setopt_array($ch,$options+[CURLOPT_PROXY=>'',CURLOPT_USERNAME=>$login,CURLOPT_PASSWORD=>$password,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_CAI