essage);throw$error;}}private static function temporaryFile(){return@tmpfile()?:throw self::temporaryFailure();}private static function write($file,string$data):void{if(@fwrite($file,$data)!==strlen($data))throw self::temporaryFailure();}public static function safeName(string$name):string{return mb_strcut(trim(preg_replace('~[\x00-\x1f\x7f/\\\\]+~','_',$name)),0,180,'UTF-8')?:'attachment';}private static function upstream():ApiError{return new ApiError(502,'MPEI_MAIL_UPSTREAM','Нет подтверждённого соединения с почтой МЭИ. Повторите позже.');}private static function temporaryFailure():ApiError{return new ApiError(503,'MPEI_MAIL_TEMPORARY_STORAGE','Сервер не смог подготовить временный файл для почты.');}}